from rest_framework.throttling import SimpleRateThrottle


class BurstRateThrottle(SimpleRateThrottle):
    """محدودیت نرخ لحظه‌ای — برای Endpointهای پرهزینه."""
    scope = "burst"

    def get_cache_key(self, request, view):
        if request.user.is_authenticated:
            ident = request.user.pk
        else:
            ident = self.get_ident(request)
        return self.cache_format % {
            "scope": self.scope,
            "ident": ident,
        }


class PlanBasedThrottle(SimpleRateThrottle):
    """نرخ بر اساس پلن کاربر."""
    scope = "plan"

    def allow_request(self, request, view):
        # نرخ را بر اساس پلن کاربر تعیین کن
        user = request.user
        if user.is_authenticated and hasattr(user, "plan"):
            rate = user.plan.rate  # مثلاً "1000/hour"
            self.rate = rate
            self.num_requests, self.duration = self.parse_rate(rate)
        return super().allow_request(request, view)

    def get_cache_key(self, request, view):
        if request.user.is_authenticated:
            ident = request.user.pk
        else:
            ident = self.get_ident(request)
        return self.cache_format % {
            "scope": self.scope,
            "ident": ident,
        }

